    build: [S('2 oz', 'Cachaça'), I('1', 'Lime, cut into small wedges'), I('4 tsp', 'White cane sugar')],
    steps: ['Gently muddle the lime and sugar in the glass.', 'Fill with cracked ice.', 'Add the cachaça.', 'Stir gently.'],
