// Riffs on the existing pages that now have a page of their own, plus the variations Tommy listed.
const RIFF_LINKS = {
  'old-fashioned': { 'Oaxaca Old Fashioned': C('oaxaca-old-fashioned') },
  manhattan: { 'Rob Roy': C('rob-roy') },
  martini: { Vesper: C('vesper') },
  sazerac: { 'Vieux Carré': C('vieux-carre') },
  daiquiri: { 'Hemingway Daiquiri': C('hemingway-daiquiri') },
  gimlet: { Southside: C('southside') },
  'last-word': { 'Naked & Famous': C('naked-and-famous') },
  'paper-plane': { 'Naked & Famous': C('naked-and-famous') },
  penicillin: { 'Gold Rush': C('gold-rush') },
  'moscow-mule': { 'Dark ’n Stormy': C('dark-n-stormy') },
  mojito: { Southside: C('southside') },
};
const RIFF_ADD = {
  martini: R('Vodka Martini', 'Vodka instead of gin.'),
  negroni: R('Americano', 'Campari and vermouth with soda, no gin.', C('americano')),
  'whiskey-sour': R('Gold Rush', 'Honey instead of sugar, no egg.', C('gold-rush')),
  mojito: R('Old Cuban', 'Aged rum, bitters and Champagne, served up.', C('old-cuban')),
};

const seeds = JSON.parse(fs.readFileSync(file, 'utf8'));
const bySlug = new Map(seeds.map((s) => [s.slug, s]));
let added = 0, updated = 0;
for (const d of DRINKS) {
  const { slug, sort, ...rest } = d;
  const ph = photos[slug];
  if (!ph) throw new Error('no photo: ' + slug);
  const data = {
    name: rest.name, family: rest.family, tagline: rest.tagline, description: rest.description,
    photo: ph.file, photoCredit: ph.credit, color: rest.color,
    glass: rest.glass, method: rest.method, ice: rest.ice, garnish: rest.garnish, tableBase: rest.tableBase, glassCard: rest.glassCard,
    build: rest.build, steps: rest.steps, flavors: rest.flavors, tasteLine: rest.tasteLine, riffs: rest.riffs,
    spiritName: rest.spiritName, spiritLine: rest.spiritLine, spiritLinkLabel: rest.spiritLinkLabel || `Learn about ${rest.spiritName.toLowerCase()}`, spiritLink: rest.spiritLink,
    pour: 'Bar lead to add our bottle', links: rest.links, say: rest.say, story: rest.story, video: vid(rest.name),
    allergyTag: rest.allergyTag || '', allergyNote: rest.allergyNote || '',
  };
  const key = 'classic/' + slug;
  const row = bySlug.get(key);
  if (row) { row.data = data; row.sort = sort; updated++; } else { seeds.push({ key, slug: key, sort, data }); added++; }
}
for (const [slug, map] of Object.entries(RIFF_LINKS)) {
  const s = bySlug.get('classic/' + slug); if (!s) continue;
  for (const r of s.data.riffs || []) if (map[r.name]) r.link = map[r.name];
}
for (const [slug, riff] of Object.entries(RIFF_ADD)) {
  const s = bySlug.get('classic/' + slug); if (!s) continue;
  if (!(s.data.riffs || []).some((r) => r.name === riff.name) && s.data.riffs.length < 4) s.data.riffs.push(riff);
}
// Moscow Mule's ginger beer pointed at the gin page by mistake.
const mule = bySlug.get('classic/moscow-mule'); const gb = mule?.data.build.find((b) => /ginger beer/i.test(b.ingredient)); if (gb && gb.link === '/spirit/gin') gb.link = '';
fs.writeFileSync(file, JSON.stringify(seeds, null, 1) + '\n');
console.log(`classics: ${added} added, ${updated} updated, ${seeds.length} total`);
